/*
 * The application ABI of libfplinux-ui.so.1: exactly the functions declared
 * in the installed headers fplinux-ui.h, fplinux-ui-screen.h,
 * fplinux-ui-text.h, fplinux-ui-menu.h, fplinux-ui-prefs.h,
 * fplinux-ui-locale.h. A new function is added here and in its header; none
 * is removed or changed while the soname stays libfplinux-ui.so.1. Every
 * other symbol, such as the fonts, the session protocol functions and the
 * xdg-shell interfaces, stays local to the library.
 */
